 "research_concepts": [
  "Defensive impact",
  "Opponent performance change",
  "Team trait reliability",
  "Half-to-half differentials"
 ],
 "methodological_questions": [
  "How to measure consistency of a team effect?",
  "What are common confounders for within-game performance changes?",
  "How to define performance metrics for halves?"
