 "historical_evidence": [
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Within-game and cross-game defensive scheme changes (inferred labels) were untestable. The inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices were consistent with label noise."
  },
  {
   "id": "FAM:SF-APPS-025",
   "status_as_recorded": "untestable",
   "finding": "Teams that abandon a suppressed play type (h2_n<=1) show a smaller matched-pair overall six-PT H1->H2 excess decline than teams that continue (h2_n>=5) was untestable. Group B (continue) caliper-0.10 CI includes 0 (p=0.386, n=255 clusters=242); Group B was a reconstructed post-hoc cohort, not a validated successful-adaptation sample."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Descriptive analysis of within-game tactical adaptation (halftime, crunch, post-run) showed play-type mix shifts (e.g., OTHER +2.26 to +2.48pp in H2). No inferential tests were performed, and the 'OTHER' label was known to be noisy."
  },
  {
   "id": "FAM:SF-APPM-057",
   "status_as_recorded": "supported",
   "finding": "The N~8-12 defensive adaptations used to certify playsheet ROBUST are genuinely distinct regimes (cosine clusters at 0.90), not near-duplicate single-knob tweaks. 11/12 and 10/11 distinct at the registered 0.90 threshold, but on n=2 matchups."
  },
  {
   "id": "FAM:SF07",
   "status_as_recorded": "supported",
   "finding": "After the opponent runs play type X, the next offensive play type Y scores above Y's unconditional H2 baseline, and every PT has a defensive aftershock (e.g., CUT +0.119 n=21,398)."
  },
  {
   "id": "FAM:SF-APPS-073",
   "status_as_recorded": "artifact",
   "finding": "Persistent Impact Score lag curves (global then within-team) were found to be an artifact. Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Persistent Impact Score Level 1 gate was found to be an artifact. Flat non-decaying lifts collapse under within-team baseline due to a team-quality confound."
  },
  {
   "id": "FAM:SF-CHT-037",
   "status_as_recorded": "artifact",
   "finding": "Sequence-memory lag effects with game-state controls were found to be an artifact. DRIVE and PNR lag-1 effects disappear with game-state controls / within-team baseline."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Attempt to measure defensive scheme change within and across games using inferred labels.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; observed failure evidence: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF-APPS-025",
   "what_failed": "Measuring the impact of adapting vs continuing a suppressed play type on H1->H2 excess decline.",
   "why": "A_unanswerable (question not answerable with the data or design); RISK:PLACEBO_DEPENDENCE; RISK:SAMPLE_SIZE_POWER; observed failure evidence: Group B caliper-0.10 CI includes 0; Group B is a reconstructed post-hoc cohort, not a validated successful-adaptation sample."
  },
  {
   "id": "FAM:SF-APPS-073",
   "what_failed": "Measuring persistent impact score lag curves (action memory).",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); observed failure evidence: Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Testing if play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2).",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); LIM:confounding; RISK:CONFOUNDING; observed failure evidence: Flat non-decaying lifts collapse under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-CHT-037",
   "what_failed": "Measuring sequence-memory lag effects with game-state controls.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); observed failure evidence: DRIVE and PNR lag-1 effects disappear with game-state controls / within-team baseline."
  }
 ],
 "evidence_establishes": [
  "Naive measurements of sequential play-type effects or within-game performance changes are highly susceptible to confounding by team quality and label errors, often leading to artifactual results (FAM:SF-APPS-073, FAM:SF-CHT-029, FAM:SF-CHT-037).",
  "Inferring specific defensive adjustments or their general impact from play-by-play data is prone to label noise and has been found untestable (FAM:SF-APPA-005, FAM:SF-APPM-021).",
  "Specific 'defensive aftershocks' on subsequent offensive plays can be consistently measured when controlling for baseline performance (FAM:SF07), indicating that defensive actions do have measurable impacts.",
  "The concept of distinct defensive adaptations can be supported, but this was on a very small sample (FAM:SF-APPM-057).",
  "Small sample sizes are a recurring limitation for isolating specific adaptation outcomes (FAM:SF-APPS-025, FAM:SF-APPM-057)."
 ],
 "evidence_does_not_establish": [
  "A robust and validated method for measuring a 'defense's effect' on opponent's overall H2-H1 performance change, as distinct from offensive execution or other game factors.",
  "Whether such a measured effect, if obtainable, constitutes a 'reliable team trait' that is consistent across games or seasons.",
  "Effective controls for all confounders when examining half-to-half performance differentials for defensive impact at a team level."
 ],
 "own_inferences": [
  "The research question, as currently phrased, is ill-posed because 'A defense's effect' on a broad H2-H1 change is difficult to isolate and quantify reliably without a more specific mechanism or intervention.",
  "The concept of 'reliability' implies a need for a robust, repeatable measure across different contexts (e.g., games, seasons, opponents), which is challenging given the observed issues with confounding and label errors in related studies.",
  "The available data allows for calculation of H1 and H2 opponent performance, but attributing the change solely to the defense's 'effect' will be highly confounded."
 ],
 "uncertainties": [
  "The precise definition of 'defense's effect' is not specified, making it unclear what specific defensive actions or outcomes are being attributed.",
  "The specific performance metric for 'opponent's H2-H1 change' (e.g., PPP, eFG%, scoring margin) is not defined.",
  "Without a clear, validated measure of 'defense's effect' and robust controls, it's uncertain if any observed H2-H1 change can be causally linked to the defense."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly suggests that measuring a broad 'defense's effect' on H2-H1 change is highly prone to confounding and label error, making it untestable as a reliable team trait. Several analogous studies attempting to isolate defensive or sequential impacts resulted in artifacts or untestable conclusions due to these very issues. This evidence shifts the decision from 'proceed' to 'do_not_proceed' because the fundamental measurement of the estimand is shown to be unreliable and confounded."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "CONFOUNDING",
    "text": "The H2-H1 change in opponent performance is influenced by numerous factors beyond the defense's specific effect, including offensive adjustments, score effects, fatigue, coaching strategies, and luck. Isolating the 'defense's effect' is extremely difficult and highly susceptible to confounding by these other variables, as demonstrated by prior artifactual findings (FAM:SF-APPS-073, FAM:SF-CHT-029, FAM:SF-CHT-037)."
   },
   {
    "code": "MEASURE_RELIABILITY",
    "text": "Defining and reliably measuring 'A defense's effect' in a way that is distinct from offensive execution or other game factors is a significant challenge. Prior attempts to infer defensive adjustments have suffered from label noise (FAM:SF-APPA-005, FAM:SF-APPM-021), suggesting that a robust, low-noise measure for 'defensive effect' on H2-H1 change is currently lacking."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [
   "FAM:SF-APPA-005",
   "FAM:SF-APPS-025",
   "FAM:SF-APPM-021",
   "FAM:SF-APPM-057",
   "FAM:SF07",
   "FAM:SF-APPS-073",
   "FAM:SF-CHT-029",
   "FAM:SF-CHT-037"
  ],
  "summary": "No prior work directly answered whether 'A defense's effect on opponents' H2-H1 change is a reliable team trait.' However, several studies explored related concepts like defensive scheme changes, within-game adaptations, and persistent impact scores. These studies consistently highlight significant methodological challenges, primarily confounding by team quality and label errors, which led to many 'untestable' or 'artifact' outcomes when attempting to isolate specific defensive or sequential effects. While granular 'defensive aftershocks' were supported, a broad team-level 'effect' on half-to-half change remains unvalidated and highly problematic."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Opponent H2-H1 performance change is a complex outcome influenced by many factors (offense's own adjustments, fatigue, score effects, coaching decisions, luck). Attributing this change specifically to 'a defense's effect' without highly sophisticated controls will lead to confounded results. Previous studies attempting to isolate similar effects have identified team quality as a major confounder, leading to artifactual findings."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The core estimand, 'a defense's effect,' is not clearly defined or easily measurable. If it relies on inferred defensive adjustments or broad performance shifts, it will likely suffer from low measurement reliability and label error, as seen in FAM:SF-APPA-005 and FAM:SF-APPM-021. A robust, validated metric for this 'effect' is a prerequisite."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While 120 team-seasons are available, if the 'effect' is small, or if significant stratification or controls are needed, the effective sample size for detecting a reliable trait might be insufficient. Previous studies on adaptation and specific effects have run into power issues (FAM:SF-APPS-025, FAM:SF-APPM-057)."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "If defensive strategies or offensive counter-strategies evolve significantly over the four seasons of data, a 'reliable team trait' might not be stationary, complicating the assessment of its reliability across the entire dataset."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.1,
  "untestable": 0.6,
  "artifact": 0.2,
  "uncertain": 0.05
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The reliability (e.g., intra-class correlation coefficient) of a team's defensive impact on opponent's half-to-half (H2-H1) offensive efficiency (points per possession, PPP). Defensive impact on H2-H1 PPP change is defined as the residual of opponent's H2-H1 PPP change after controlling for baseline H1 PPP, team strength, opponent strength, H1 score margin, and specific offensive play-type mix changes.",
  "unit": "Team-season as the unit for calculating reliability. Game as the unit for calculating the H2-H1 PPP change and defensive impact.",
  "sample": "NBA 2022-23 to 2025-26 regular season and playoffs. All available games for the 120 team-seasons.",
  "power": "Not estimable given the lack of a validated estimand and high risk of confounding. A minimum of 30 games per team-season would be needed to estimate a team's 'effect' with reasonable precision.",
  "controls": "To mitigate confounding, the H2-H1 PPP change would need to be regressed on: opponent H1 PPP, team's average defensive PPP, opponent's average offensive PPP, H1 score margin, H1 pace, H2 pace, and changes in offensive play-type distribution from H1 to H2. Further controls for player availability (injuries, foul trouble) and specific match-up adjustments would ideally be included but are difficult to implement without more granular data.",
  "falsification": "A strong falsification test would be to demonstrate that the 'defensive effect' measure is independent of team offensive strength and opponent offensive strength, and that it does not collapse into an artifact when controlling for game-state variables and within-team baselines (e.g., by demeaning at the team-season level).",
  "multiplicity": "If multiple definitions of 'defensive effect' or 'opponent performance' are explored, adjust p-values using Bonferroni correction or FDR control.",
  "decision_rule": "The question is deemed 'testable' if a well-controlled, non-artifactual measure of 'defensive effect on H2-H1 change' can be established. 'Reliability' would then be assessed via intra-class correlation (ICC) with a pre-specified threshold (e.g., ICC > 0.4 for moderate reliability). Given the high risks, the current decision is 'do_not_proceed' as the foundational measure is likely untestable or an artifact."
 }
}

